import{_ as a,o as e,c as s,a2 as n}from"./chunks/framework.CLq81i8L.js";const g=JSON.parse('{"title":"Flow 产品设计文档","description":"","frontmatter":{},"headers":[],"relativePath":"flow/design/index.md","filePath":"flow/design/index.md","lastUpdated":1785288787000}'),d={name:"flow/design/index.md"};function r(l,t,o,i,h,c){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="flow-产品设计文档" tabindex="-1">Flow 产品设计文档 <a class="header-anchor" href="#flow-产品设计文档" aria-label="Permalink to &quot;Flow 产品设计文档&quot;">​</a></h1><blockquote><p>页面线框、交互流、运行时架构 — 基于 <code>flow/src</code> + <code>flow-shared</code> 当前实现</p></blockquote><h2 id="文档索引" tabindex="-1">文档索引 <a class="header-anchor" href="#文档索引" aria-label="Permalink to &quot;文档索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>范围</th></tr></thead><tbody><tr><td><a href="./overview.html">信息架构与布局</a></td><td>路由、AppLayout、qiankun、嵌入页</td></tr><tr><td><a href="./designer.html">流程设计器</a></td><td>三栏 BPMN 画布、节点面板、模拟执行</td></tr><tr><td><a href="./instances-tasks.html">实例与任务</a></td><td>实例列表、审批收件箱、任务操作</td></tr><tr><td><a href="./runtime.html"><strong>运行时架构</strong></a></td><td>FlowEngine、Token 模型、服务端执行 vs 前端可视化</td></tr></tbody></table><h2 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to &quot;设计原则&quot;">​</a></h2><ol><li><strong>设计/执行分离</strong>：<code>flow/</code> 负责 BPMN 可视化编排；<code>flow-shared/FlowEngine</code> 在服务端执行</li><li><strong>flowGraph 为真源</strong>：Vue Flow nodes/edges ↔ <code>FlowGraph</code> JSON 双向序列化</li><li><strong>模拟 ≠ 运行时</strong>：<code>useSimulation</code> 仅设计器预览，不调用 FlowEngine</li><li><strong>表单绑定 Editor</strong>：UserTask 通过 <code>formPublishId</code> + iframe 嵌入 PublishView</li><li><strong>AI 协同</strong>：WebSocket <code>onAiApply</code> / <code>onAiPublished</code> 接收 AI 生成结果</li></ol><h2 id="核心系统" tabindex="-1">核心系统 <a class="header-anchor" href="#核心系统" aria-label="Permalink to &quot;核心系统&quot;">​</a></h2><h3 id="bpmn-设计器" tabindex="-1">BPMN 设计器 <a class="header-anchor" href="#bpmn-设计器" aria-label="Permalink to &quot;BPMN 设计器&quot;">​</a></h3><ul><li><strong>三栏布局</strong>：左侧节点面板、中间画布、右侧属性面板</li><li><strong>节点类型</strong>：StartEvent、EndEvent、UserTask、ServiceTask、ExclusiveGateway、ParallelGateway 等</li><li><strong>拖拽创建</strong>：从节点面板拖拽到画布创建节点</li><li><strong>连线编辑</strong>：点击节点端口拖拽创建连线</li><li><strong>属性配置</strong>：选中节点/连线后在右侧面板配置属性</li></ul><h3 id="flowengine-运行时" tabindex="-1">FlowEngine 运行时 <a class="header-anchor" href="#flowengine-运行时" aria-label="Permalink to &quot;FlowEngine 运行时&quot;">​</a></h3><ul><li><strong>Token 模型</strong>：流程实例 Token 驱动执行</li><li><strong>条件分支</strong>：Exclusive Gateway 条件路由</li><li><strong>并行分支</strong>：Parallel Gateway 多分支并行</li><li><strong>用户任务</strong>：UserTask 人工审批节点</li><li><strong>服务任务</strong>：ServiceTask 自动执行节点</li><li><strong>子流程</strong>：SubProcess 嵌套子流程</li></ul><h3 id="实例与任务" tabindex="-1">实例与任务 <a class="header-anchor" href="#实例与任务" aria-label="Permalink to &quot;实例与任务&quot;">​</a></h3><ul><li><strong>流程实例</strong>：流程定义的运行实例，包含当前状态、变量、历史</li><li><strong>任务收件箱</strong>：待办任务列表、批量操作、委托转办</li><li><strong>审批历史</strong>：完整审批轨迹、意见记录</li><li><strong>超时处理</strong>：节点超时自动通过/拒绝</li></ul><h3 id="ai-协同" tabindex="-1">AI 协同 <a class="header-anchor" href="#ai-协同" aria-label="Permalink to &quot;AI 协同&quot;">​</a></h3><ul><li><strong>对话式流程生成</strong>：自然语言描述自动生成 BPMN</li><li><strong>WebSocket 事件</strong>：<code>onAiApply</code> 接收 AI 生成结果</li><li><strong>流程优化建议</strong>：AI 分析流程瓶颈并提供优化建议</li></ul><h2 id="页面地图" tabindex="-1">页面地图 <a class="header-anchor" href="#页面地图" aria-label="Permalink to &quot;页面地图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AppLayout (侧栏，嵌入时隐藏)</span></span>
<span class="line"><span>├── /list               FlowListView           流程定义列表</span></span>
<span class="line"><span>├── /instances          FlowInstanceListView   流程实例</span></span>
<span class="line"><span>├── /instance/:id       FlowInstanceDetailView 实例详情（运行时图）</span></span>
<span class="line"><span>├── /tasks              TaskInboxView          我的任务</span></span>
<span class="line"><span>├── /monitor            FlowMonitorDashboard   流程监控</span></span>
<span class="line"><span>├── /templates          FlowTemplateView       流程模板</span></span>
<span class="line"><span>├── /stats              FlowStatsView          统计报表</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── /designer?id=       FlowDesigner           全屏设计器</span></span>
<span class="line"><span>└── /embed/*            嵌入页（Editor/Shell）</span></span></code></pre></div><h2 id="设计态-vs-运行态" tabindex="-1">设计态 vs 运行态 <a class="header-anchor" href="#设计态-vs-运行态" aria-label="Permalink to &quot;设计态 vs 运行态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>设计态（Designer）</th><th>运行态（Runtime）</th></tr></thead><tbody><tr><td>组件</td><td>FlowDesigner</td><td>FlowInstanceDetailView</td></tr><tr><td>数据</td><td>流程定义（FlowGraph）</td><td>流程实例（ProcessInstance）</td></tr><tr><td>交互</td><td>拖拽、连线、配置</td><td>审批、填写、提交</td></tr><tr><td>执行</td><td>模拟执行（useSimulation）</td><td>真实执行（FlowEngine）</td></tr><tr><td>状态</td><td>草稿、已发布</td><td>运行中、已完成、已终止</td></tr></tbody></table><h2 id="节点类型" tabindex="-1">节点类型 <a class="header-anchor" href="#节点类型" aria-label="Permalink to &quot;节点类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>节点</th><th>图标</th><th>说明</th></tr></thead><tbody><tr><td>StartEvent</td><td>⭕</td><td>流程开始</td></tr><tr><td>EndEvent</td><td>⏹️</td><td>流程结束</td></tr><tr><td>UserTask</td><td>👤</td><td>人工审批任务</td></tr><tr><td>ServiceTask</td><td>⚙️</td><td>自动服务任务</td></tr><tr><td>ExclusiveGateway</td><td>◇</td><td>排他网关（条件分支）</td></tr><tr><td>ParallelGateway</td><td>◆</td><td>并行网关（多分支并行）</td></tr><tr><td>SubProcess</td><td>📦</td><td>子流程</td></tr></tbody></table><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="/schema-platform/docs/flow/architecture.html">架构设计</a></td><td>分层、flow-shared 边界、Store</td></tr><tr><td><a href="/schema-platform/docs/flow/changelog.html">更新日志</a></td><td>迭代记录</td></tr><tr><td><a href="/schema-platform/docs/editor/capabilities.html">能力清单</a></td><td>Editor 完整能力矩阵</td></tr><tr><td><a href="/schema-platform/docs/ai/">AI 平台</a></td><td>AI 对话、工作流、RAG</td></tr><tr><td><a href="/schema-platform/docs/extend/">扩展开发</a></td><td>自定义模型、Skill、模板</td></tr></tbody></table>`,23)])])}const b=a(d,[["render",r]]);export{g as __pageData,b as default};
